<script setup lang="ts">
import { computed, onMounted, ref, watch } from 'vue'
import { readExcel, defaultColumns, mapRows, normalize } from './excel'
import { classify, names, previousWeekOf, validateConfig, weekOf } from './report'
import { emptyConfig, loadConfig, saveConfig } from './storage'
import { exportReports } from './export'
import { applyDefaultGroups, sourceBrandNames } from './preset'
import type { Config, Row, WorkbookFormat } from './types'

const config = ref<Config>(emptyConfig())
const tab = ref('dashboard')
const file = ref<File>()
const source = ref<{ headers:string[]; rows:Row[]; sheet:string; headerRow:number; format:WorkbookFormat }>()
const defaultDate = previousWeekOf().start
const date = ref(`${defaultDate.getFullYear()}-${String(defaultDate.getMonth() + 1).padStart(2, '0')}-${String(defaultDate.getDate()).padStart(2, '0')}`)
const custom = ref(false), from = ref(''), to = ref('')
const busy = ref(false), status = ref(''), error = ref('')
const progress = ref(0)
const directory = ref<FileSystemDirectoryHandle>()
const search = ref('')
let ready = false
onMounted(async()=>{ try { const saved = await loadConfig(); if (saved?.version === 1) config.value = saved } catch(e) { error.value = String(e) } ready = true })
watch(config, async v => { if (ready) try { await saveConfig(v) } catch(e) { error.value = String(e) } }, {deep:true})
const range = computed(()=>{ try { if (custom.value) { const start = new Date(`${from.value}T12:00:00`), end = new Date(`${to.value}T12:00:00`); if (isNaN(start.getTime()) || isNaN(end.getTime()) || end < start) throw Error(); return {start,end} } return weekOf(date.value) } catch { return null } })
const rows = computed(()=> source.value ? mapRows(source.value.rows,config.value.columns) : [])
const classification = computed(()=> classify(rows.value,config.value.brands))
const previewNames = computed(()=> range.value ? names(config.value,range.value.start,range.value.end) : null)
const issues = computed(()=> { const e = validateConfig(config.value); if (!range.value) e.push('Khoảng ngày không hợp lệ'); if (!config.value.columns.some(c=>normalize(c.title)==='hãng')) e.push('Thiếu cột Hãng trong mẫu xuất'); for (const c of config.value.columns.filter(c=>c.required)) if (!source.value?.headers.some(h=>normalize(h)===normalize(c.source))) e.push(`Thiếu cột nguồn: ${c.source}`); if (!Number.isFinite(config.value.groupRowHeight) || config.value.groupRowHeight < 25 || config.value.groupRowHeight > 400) e.push('Chiều cao hàng file gửi cần từ 25 đến 400 pt'); if (config.value.exportMode==='strict' && classification.value.unknownRows.length) e.push(`${classification.value.unknownRows.length} dòng chưa phân loại: chế độ Strict chặn xuất`); return e })
const plannedFiles = computed(()=> 1 + config.value.groups.filter(g=>g.active && (!g.skipEmpty || classification.value.grouped.has(g.id))).length + (config.value.exportMode==='flexible' && classification.value.unknownRows.length ? 1 : 0))
async function importFile(f?:File) { if (!f) return; busy.value=true; error.value=''; try { const loaded = await readExcel(f); file.value=f; source.value=loaded; if (!config.value.columns.length) config.value.columns=defaultColumns(loaded.headers); if (!config.value.groups.length && !config.value.brands.length) config.value=applyDefaultGroups(config.value,sourceBrandNames(loaded.rows)); status.value=`Đã đọc ${loaded.rows.length} dòng từ sheet ${loaded.sheet}.` } catch(e) { error.value=String(e) } finally { busy.value=false } }
function applyPreset() { if (!source.value) { error.value='Hãy nhập Excel trước để tạo file riêng cho các hãng còn lại.'; return } if (config.value.groups.length && !confirm('Thay thế toàn bộ danh mục, nhóm và hãng hiện tại bằng mẫu mặc định?')) return; config.value=applyDefaultGroups(config.value,sourceBrandNames(source.value.rows)); status.value='Đã áp dụng nhóm HN, HCM, Sao Thủ Đô và file riêng cho các hãng còn lại.' }
function addCategory() { const name=prompt('Tên danh mục?')?.trim(); if(name) config.value.categories.push({id:crypto.randomUUID(),name}) }
function addGroup(categoryId:string) { const name=prompt('Tên nhóm xuất file?')?.trim(); if(name) config.value.groups.push({id:crypto.randomUUID(),categoryId,name,fileName:name,active:true,skipEmpty:true}) }
function addBrand(groupId:string, name?:string) { const value=(name || prompt('Tên hãng?') || '').trim(); if(!value)return; if(config.value.brands.some(b=>[b.name,...b.aliases].some(a=>normalize(a)===normalize(value)))) {error.value='Tên hãng đã tồn tại';return} config.value.brands.push({id:crypto.randomUUID(),name:value,aliases:[],groupId,active:true}) }
function brandCount(name:string, aliases:string[]) { const keys=new Set([name,...aliases].map(normalize)); return source.value?.rows.filter(row=>{ const key=Object.keys(row).find(k=>normalize(k)==='hãng');return key && keys.has(normalize(row[key])) }).length ?? 0 }
function removeGroup(id:string) { const group=config.value.groups.find(g=>g.id===id); if(!group || !confirm(`Xóa nhóm ${group.name} và các hãng thuộc nhóm?`))return; config.value.brands=config.value.brands.filter(b=>b.groupId!==id);config.value.groups=config.value.groups.filter(g=>g.id!==id) }
function removeCategory(id:string) { if(config.value.groups.some(g=>g.categoryId===id)){error.value='Hãy chuyển hoặc xóa các nhóm trước.';return} if(confirm('Xóa danh mục này?'))config.value.categories=config.value.categories.filter(c=>c.id!==id) }
function removeBrand(id:string) { if(confirm('Xóa hãng này?'))config.value.brands=config.value.brands.filter(b=>b.id!==id) }
function addUnknown(name:string, groupId:string) { if(name==='(trống)'){error.value='Dòng thiếu Hãng sẽ nằm trong file ChuaPhanLoai ở chế độ Flexible.';return} addBrand(groupId,name) }
function addUnknownSeparate(name:string) { if(name==='(trống)'){error.value='Dòng thiếu Hãng sẽ nằm trong file ChuaPhanLoai ở chế độ Flexible.';return} let category=config.value.categories[0]; if(!category){category={id:crypto.randomUUID(),name:'Hãng riêng'};config.value.categories.push(category)} const id=crypto.randomUUID();config.value.groups.push({id,categoryId:category.id,name,fileName:name,active:true,skipEmpty:true});addBrand(id,name) }
function addColumn() { config.value.columns.push({id:crypto.randomUUID(),title:'Cột mới',source:'',required:false}) }
function resetColumns() { if (source.value && confirm('Khôi phục mẫu cột từ file nguồn?')) config.value.columns=defaultColumns(source.value.headers) }
function resetConfig() { if (confirm('Khôi phục cấu hình rỗng?')) config.value=emptyConfig() }
async function chooseDirectory() { try { if(!window.showDirectoryPicker) throw new Error('Trình duyệt không hỗ trợ chọn thư mục. Có thể xuất ZIP.'); directory.value=await window.showDirectoryPicker() } catch(e) { error.value=e instanceof DOMException && e.name==='AbortError' ? 'Bạn đã hủy chọn thư mục. Có thể chọn lại hoặc xuất ZIP.' : String(e) } }
async function doExport() { if(!range.value || !source.value || issues.value.length)return; const count=classification.value.unknownRows.length; const confirmed=count && config.value.exportMode==='confirmed-skip' ? confirm(`${count} dòng chưa phân loại sẽ không nằm trong các file nhóm. File main vẫn giữ đủ ${rows.value.length} dòng. Tiếp tục?`) : false; if(count && config.value.exportMode==='confirmed-skip' && !confirmed)return; busy.value=true;progress.value=0;error.value='';status.value='Đang tạo file...';try { const files=await exportReports(rows.value,config.value,range.value.start,range.value.end,directory.value,!!confirmed,(done,total,file)=>{progress.value=Math.round(done/total*100);status.value=`Đang xử lý ${file} (${done}/${total})`},existing=>confirm(`Các file sau đã tồn tại:\n${existing.join('\n')}\nGhi đè các file này?`),source.value.format);status.value=`Đã xuất ${files.length} file: ${files.join(', ')}` } catch(e) {error.value=String(e);status.value=''} finally {busy.value=false} }
function backup() { const blob=new Blob([JSON.stringify(config.value,null,2)],{type:'application/json'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='excel-report-config.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000) }
async function restore(f?:File) { if(!f)return;try { const data=JSON.parse(await f.text()) as Config;if(data.version!==1 || !Array.isArray(data.groups) || !Array.isArray(data.columns))throw Error('Phiên bản hoặc cấu trúc cấu hình không hợp lệ');if(confirm('Thay thế toàn bộ cấu hình hiện tại?'))config.value={...emptyConfig(),...data} }catch(e){error.value=String(e)} }
</script>
<template>
<div class="layout"><aside><div class="logo">◫ <span>Báo cáo<br><small>HÀNH TRÌNH</small></span></div><nav><button v-for="item in [['dashboard','Tổng quan'],['brands','Quản lý hãng'],['template','Mẫu cột'],['settings','Cài đặt']]" :key="item[0]" :class="{active:tab===item[0]}" @click="tab=item[0]">{{item[1]}}</button></nav><div class="aside-note">Dữ liệu Excel chỉ được xử lý trong trình duyệt.</div></aside>
<main><header><div><p class="eyebrow">BÁO CÁO HÀNH TRÌNH</p><h1>{{ {dashboard:'Tổng quan',brands:'Quản lý hãng',template:'Mẫu cột',settings:'Cài đặt'}[tab as 'dashboard'|'brands'|'template'|'settings'] }}</h1></div><span class="badge">XỬ LÝ TRÊN TRÌNH DUYỆT</span></header><p v-if="error" class="alert error">{{error}} <button @click="error=''">×</button></p><p v-if="status" class="alert good">{{status}}</p>
<template v-if="tab==='dashboard'"><div class="grid two"><section class="card"><h2>1. Nhập Excel</h2><label class="drop" @dragover.prevent @drop.prevent="importFile($event.dataTransfer?.files[0])"><input type="file" accept=".xlsx" @change="importFile(($event.target as HTMLInputElement).files?.[0])"><strong>Chọn hoặc kéo thả file .xlsx</strong><small>File gốc được giữ nguyên</small></label><p v-if="file" class="muted">{{file.name}} · {{(file.size/1024).toFixed(1)}} KB · {{source?.rows.length}} dòng · Header dòng {{source?.headerRow}}</p></section><section class="card"><h2>2. Chọn kỳ báo cáo</h2><label>Ngày bất kỳ <input v-model="date" type="date" :disabled="custom"></label><label class="check"><input v-model="custom" type="checkbox"> Khoảng ngày tùy chỉnh</label><div v-if="custom" class="inline"><input v-model="from" type="date"><input v-model="to" type="date"></div><p v-if="range" class="muted">{{range.start.toLocaleDateString('vi-VN')}} – {{range.end.toLocaleDateString('vi-VN')}}</p></section></div>
<div class="grid stats"><div class="stat"><strong>{{source?.rows.length ?? 0}}</strong><span>Dòng nguồn</span></div><div class="stat"><strong>{{rows.length}}</strong><span>Dòng main</span></div><div class="stat"><strong>{{classification.grouped.size}}</strong><span>Nhóm có dữ liệu</span></div><div class="stat"><strong>{{classification.unknown.size}}</strong><span>Hãng chưa phân loại</span></div></div>
<div class="grid two"><section class="card"><h2>3. Kiểm tra</h2><p v-if="classification.unknownRows.length" class="issue">{{classification.unknownRows.length}} dòng chưa phân loại · {{config.exportMode === 'flexible' ? 'sẽ nằm trong ChuaPhanLoai' : config.exportMode === 'strict' ? 'đang chặn xuất' : 'cần xác nhận trước khi xuất'}}</p><p v-if="!source" class="muted">Nhập file Excel để xem dữ liệu.</p><ul v-else><li v-for="item in issues" :key="item" class="issue">{{item}}</li><li v-if="!issues.length" class="ok">Không phát hiện lỗi. {{[...classification.grouped.values()].reduce((n,v)=>n+v.length,0)}} + {{[...classification.unknown.values()].reduce((n,v)=>n+v,0)}} = {{rows.length}} dòng.</li></ul><div v-if="classification.unknown.size"><h3>Hãng chưa phân loại</h3><div v-for="[name,count] in classification.unknown" :key="name" class="unknown"><span>{{name}} ({{count}})</span><select :disabled="name === '(trống)'" @change="addUnknown(name,($event.target as HTMLSelectElement).value);($event.target as HTMLSelectElement).value='' "><option value="">Thêm vào nhóm...</option><option v-for="g in config.groups" :key="g.id" :value="g.id">{{g.name}}</option></select><button :disabled="name === '(trống)'" @click="addUnknownSeparate(name)">Xuất riêng</button></div></div></section><section class="card"><h2>4. Xuất báo cáo · {{plannedFiles}} file</h2><p class="muted">{{previewNames?.folder ?? 'Chưa chọn ngày'}}</p><ul v-if="previewNames"><li>{{previewNames.main}} · {{rows.length}} dòng</li><li v-for="g in config.groups.filter(x=>x.active && (!x.skipEmpty || classification.grouped.has(x.id)))" :key="g.id">{{previewNames.group(g.fileName)}} · {{classification.grouped.get(g.id)?.length ?? 0}} dòng</li><li v-if="config.exportMode === 'flexible' && classification.unknownRows.length">{{previewNames.group('ChuaPhanLoai')}} · {{classification.unknownRows.length}} dòng</li></ul><progress v-if="busy" :value="progress" max="100" class="export-progress"></progress><button class="secondary" @click="chooseDirectory">{{directory ? 'Đã chọn thư mục cha' : 'Chọn thư mục cha'}}</button><button class="primary" :disabled="busy || !source || !!issues.length" @click="doExport">{{busy?'Đang xử lý...':directory?'Xuất tất cả vào thư mục':'Tải ZIP tất cả file'}}</button></section></div><section v-if="rows.length" class="card"><h2>Xem trước main</h2><div class="table-wrap"><table><thead><tr><th v-for="c in config.columns" :key="c.id">{{c.title}}</th></tr></thead><tbody><tr v-for="(row,i) in rows.slice(0,5)" :key="i"><td v-for="c in config.columns" :key="c.id">{{row[c.title]}}</td></tr></tbody></table></div></section></template>
<template v-else-if="tab==='brands'"><div class="toolbar"><input v-model="search" placeholder="Tìm hãng hoặc nhóm..."><button @click="applyPreset">Áp dụng nhóm mặc định</button><button class="primary" @click="addCategory">+ Danh mục</button></div><p v-if="!config.categories.length" class="empty">Chưa có danh mục. Tạo danh mục để bắt đầu.</p><section v-for="cat in config.categories" :key="cat.id" class="card"><div class="row"><h2><input v-model="cat.name"></h2><button @click="addGroup(cat.id)">+ Nhóm</button><button class="danger" @click="removeCategory(cat.id)">Xóa</button></div><div v-for="g in config.groups.filter(x=>x.categoryId===cat.id && (!search || normalize(x.name).includes(normalize(search)) || config.brands.some(b=>b.groupId===x.id && normalize(b.name).includes(normalize(search)))))" :key="g.id" class="group"><div class="row"><input v-model="g.name" aria-label="Tên nhóm"><input v-model="g.fileName" aria-label="Tên file nhóm" placeholder="Tên file"><label class="check"><input v-model="g.active" type="checkbox"> Bật</label><label class="check"><input v-model="g.skipEmpty" type="checkbox"> Bỏ qua rỗng</label><button @click="addBrand(g.id)">+ Hãng</button><button class="danger" @click="removeGroup(g.id)">Xóa</button></div><div v-for="b in config.brands.filter(x=>x.groupId===g.id)" :key="b.id" class="brand row"><input v-model="b.name" aria-label="Tên hãng"><input :value="b.aliases.join(', ')" aria-label="Alias" placeholder="Alias, cách nhau dấu phẩy" @change="b.aliases=($event.target as HTMLInputElement).value.split(',').map(x=>x.trim()).filter(Boolean)"><span>{{brandCount(b.name,b.aliases)}} dòng</span><select v-model="b.groupId"><option v-for="target in config.groups" :key="target.id" :value="target.id">{{target.name}}</option></select><label class="check"><input v-model="b.active" type="checkbox"> Bật</label><button class="danger" @click="removeBrand(b.id)">Xóa</button></div></div></section></template>
<template v-else-if="tab==='template'"><section class="card"><div class="row"><h2>Ánh xạ cột</h2><button @click="addColumn">+ Cột</button><button :disabled="!source" @click="resetColumns">Khôi phục từ nguồn</button></div><p class="muted">Với định dạng nguồn mẫu, thứ tự cột đã được đối chiếu với file main mẫu.</p><div v-for="(c,i) in config.columns" :key="c.id" class="column row"><span>{{i+1}}</span><input v-model="c.title" aria-label="Tên cột xuất"><select v-model="c.source"><option value="">Cột trống</option><option v-for="h in source?.headers" :key="h" :value="h">{{h}}</option></select><label class="check"><input v-model="c.required" type="checkbox"> Bắt buộc</label><button :disabled="i===0" @click="[config.columns[i-1],config.columns[i]]=[config.columns[i],config.columns[i-1]]">↑</button><button :disabled="i===config.columns.length-1" @click="[config.columns[i+1],config.columns[i]]=[config.columns[i],config.columns[i+1]]">↓</button><button class="danger" @click="config.columns.splice(i,1)">×</button></div></section></template>
<template v-else><section class="card"><h2>Quy tắc tên</h2><p class="muted">Biến hỗ trợ: {start}, {end}, {shortStart}, {shortEnd}, {folder}, {group}</p><label>Tên thư mục gốc<input v-model="config.folderName"></label><label>File main<input v-model="config.mainPattern"></label><label>File nhóm<input v-model="config.groupPattern"></label><label>Thư mục báo cáo<input v-model="config.folderPattern"></label></section><section class="card"><h2>Xử lý dòng chưa phân loại</h2><label>Chế độ xuất<select v-model="config.exportMode"><option value="flexible">Flexible — xuất file ChuaPhanLoai</option><option value="strict">Strict — chặn xuất</option><option value="confirmed-skip">Confirmed Skip — xác nhận bỏ khỏi file nhóm</option></select></label><label>Chiều cao hàng file gửi (pt)<input v-model.number="config.groupRowHeight" type="number" min="25" max="400" step="5"></label><p class="muted">File main luôn giữ đủ dữ liệu nguồn.</p></section><section class="card"><h2>Sao lưu cấu hình</h2><div class="row"><button @click="backup">Tải JSON</button><label class="file-button">Nhập JSON<input type="file" accept=".json" @change="restore(($event.target as HTMLInputElement).files?.[0])"></label><button class="danger" @click="resetConfig">Khôi phục mặc định</button></div></section></template>
<footer class="site-footer">Phát triển bởi <strong>Minh Hiếu</strong></footer>
</main></div>
</template>



